    as: 'medications'
});

Medication.belongsTo(User, {
    foreignKey: 'userId',
    as: 'user'
});

User.hasMany(MedicationHistory, {
    foreignKey: 'userId',
    as: 'history'
});

MedicationHistory.belongsTo(User, {
    foreignKey: 'userId',
    as: 'user'
});

Medication.hasMany(MedicationHistory, {
    foreignKey: 'medicationId',
    as: 'history'
});

MedicationHistory.belongsTo(Medication, {
    foreignKey: 'medicationId',
    as: 'medication'
});

